Here is the commit message:
ipv4: icmp: fix null-ptr-deref in icmp_build_probe()

ipv6_stub->ipv6_dev_find() may return ERR_PTR(-EAFNOSUPPORT) when the
IPv6 stack is not active (CONFIG_IPV6=m and not loaded), and passing
this error pointer to dev_hold() will cause a kernel crash with
null-ptr-deref.

Instead, silently discard the request. RFC 8335 does not appear to
define a specific response for the case where an IPv6 interface
identifier is syntactically valid but the implementation cannot perform
the lookup at runtime, and silently dropping the request may safer than
misreporting "No Such Interface".

Fixes: d329ea5bd884 ("icmp: add response to RFC 8335 PROBE messages")
Signed-off-by: Yiqi Sun <sunyiqixm@gmail.com>
Link: https://patch.msgid.link/20260402070419.2291578-1-sunyiqixm@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function `icmp_build_probe()` in `net/ipv4/icmp.c` calls `ipv6_stub->ipv6_dev_find()` to look up an IPv6 interface. However, when the IPv6 stack is not active (e.g., `CONFIG_IPV6=m` and not loaded), this function returns `ERR_PTR(-EAFNOSUPPORT)` instead of a valid `struct net_device *`. The code then passes this error pointer directly to `dev_hold(dev)`, which attempts to dereference an invalid address, causing a null-pointer dereference. The root cause is the missing error check after the `ipv6_dev_find()` call.

Here is the patch:

 bool icmp_build_probe(struct sk_buff *skb, struct icmphdr *icmphdr)
 {
 	struct net *net = dev_net_rcu(skb->dev);
 	struct icmp_ext_hdr *ext_hdr, _ext_hdr;
 	struct icmp_ext_echo_iio *iio, _iio;
 	struct inet6_dev *in6_dev;
 	struct in_device *in_dev;
 	struct net_device *dev;
 	char buff[IFNAMSIZ];
 	u16 ident_len;
 	u8 status;

 	if (!READ_ONCE(net->ipv4.sysctl_icmp_echo_enable_probe))
 		return false;

 	/* We currently only support probing interfaces on the proxy node
 	 * Check to ensure L-bit is set
 	 */
 	if (!(ntohs(icmphdr->un.echo.sequence) & 1))
 		return false;
 	/* Clear status bits in reply message */
 	icmphdr->un.echo.sequence &= htons(0xFF00);
 	if (icmphdr->type == ICMP_EXT_ECHO)
 		icmphdr->type = ICMP_EXT_ECHOREPLY;
 	else
 		icmphdr->type = ICMPV6_EXT_ECHO_REPLY;
 	ext_hdr = skb_header_pointer(skb, 0, sizeof(_ext_hdr), &_ext_hdr);
 	/* Size of iio is class_type dependent.
 	 * Only check header here and assign length based on ctype in the switch statement
 	 */
 	iio = skb_header_pointer(skb, sizeof(_ext_hdr), sizeof(iio->extobj_hdr), &_iio);
 	if (!ext_hdr || !iio)
 		goto send_mal_query;
 	if (ntohs(iio->extobj_hdr.length) <= sizeof(iio->extobj_hdr) ||
 	    ntohs(iio->extobj_hdr.length) > sizeof(_iio))
 		goto send_mal_query;
 	ident_len = ntohs(iio->extobj_hdr.length) - sizeof(iio->extobj_hdr);
 	iio = skb_header_pointer(skb, sizeof(_ext_hdr),
 				 sizeof(iio->extobj_hdr) + ident_len, &_iio);
 	if (!iio)
 		goto send_mal_query;

 	status = 0;
 	dev = NULL;
 	switch (iio->extobj_hdr.class_type) {
 	case ICMP_EXT_ECHO_CTYPE_NAME:
 		if (ident_len >= IFNAMSIZ)
 			goto send_mal_query;
 		memset(buff, 0, sizeof(buff));
 		memcpy(buff, &iio->ident.name, ident_len);
 		dev = dev_get_by_name(net, buff);
 		break;
 	case ICMP_EXT_ECHO_CTYPE_INDEX:
 		if (ident_len != sizeof(iio->ident.ifindex))
 			goto send_mal_query;
 		dev = dev_get_by_index(net, ntohl(iio->ident.ifindex));
 		break;
 	case ICMP_EXT_ECHO_CTYPE_ADDR:
 		if (ident_len < sizeof(iio->ident.addr.ctype3_hdr) ||
 		    ident_len != sizeof(iio->ident.addr.ctype3_hdr) +
 				 iio->ident.addr.ctype3_hdr.addrlen)
 			goto send_mal_query;
 		switch (ntohs(iio->ident.addr.ctype3_hdr.afi)) {
 		case ICMP_AFI_IP:
 			if (iio->ident.addr.ctype3_hdr.addrlen != sizeof(struct in_addr))
 				goto send_mal_query;
 			dev = ip_dev_find(net, iio->ident.addr.ip_addr.ipv4_addr);
 			break;
 #if IS_ENABLED(CONFIG_IPV6)
 		case ICMP_AFI_IP6:
 			if (iio->ident.addr.ctype3_hdr.addrlen != sizeof(struct in6_addr))
 				goto send_mal_query;
 			dev = ipv6_stub->ipv6_dev_find(net, &iio->ident.addr.ip_addr.ipv6_addr, dev);
+			/*
+			 * If IPv6 identifier lookup is unavailable, silently
+			 * discard the request instead of misreporting NO_IF.
+			 */
+			if (IS_ERR(dev))
+				return false;
+
 			dev_hold(dev);
 			break;
 #endif
 		default:
 			goto send_mal_query;
 		}
 		break;
 	default:
 		goto send_mal_query;
 	}
 	if (!dev) {
 		icmphdr->code = ICMP_EXT_CODE_NO_IF;
 		return true;
 	}
 	/* Fill bits in reply message */
 	if (dev->flags & IFF_UP)
 		status |= ICMP_EXT_ECHOREPLY_ACTIVE;

 	in_dev = __in_dev_get_rcu(dev);
 	if (in_dev && rcu_access_pointer(in_dev->ifa_list))
 		status |= ICMP_EXT_ECHOREPLY_IPV4;

 	in6_dev = __in6_dev_get(dev);
 	if (in6_dev && !list_empty(&in6_dev->addr_list))
 		status |= ICMP_EXT_ECHOREPLY_IPV6;

 	dev_put(dev);
 	icmphdr->un.echo.sequence |= htons(status);
 	return true;
 send_mal_query:
 	icmphdr->code = ICMP_EXT_CODE_MAL_QUERY;
 	return true;
 }
 EXPORT_SYMBOL_GPL(icmp_build_probe);


